<div class="page-heading"><div><p class="eyebrow">Vendor workspace</p><h1>Reviews</h1><p>Read student feedback from completed orders and reply once with helpful information.</p></div></div>
<?php if ($reviews): ?><div class="review-list"><?php foreach ($reviews as $review): ?><article class="review-card"><div class="spread"><div><strong><?= h($review['food_name']) ?></strong><div class="muted small"><?= h($review['full_name']) ?> · <?= h($review['order_number']) ?> · <?= h(format_datetime($review['created_at'], 'M j, Y')) ?></div></div><span class="stars" aria-label="<?= (int) $review['rating'] ?> out of 5 stars"><?= str_repeat('★', (int) $review['rating']) ?><?= str_repeat('☆', 5-(int) $review['rating']) ?></span></div><?php if ($review['comment']): ?><p><?= nl2br(h($review['comment'])) ?></p><?php endif; ?>
  <?php if ($review['vendor_response']): ?><div class="vendor-reply"><strong>Your response</strong><p><?= nl2br(h($review['vendor_response'])) ?></p></div><?php endif; ?>
  <details><summary class="small"><?= $review['vendor_response'] ? 'Edit response' : 'Reply to review' ?></summary><form method="post" action="<?= h(app_url('vendor.review.reply')) ?>" class="stack" style="margin-top:9px" data-submit-feedback><?= csrf_field() ?><input type="hidden" name="review_id" value="<?= (int) $review['id'] ?>"><div class="form-field"><label class="sr-only" for="reply-<?= (int) $review['id'] ?>">Vendor response</label><textarea id="reply-<?= (int) $review['id'] ?>" name="vendor_response" maxlength="1000" rows="3" required><?= h($review['vendor_response'] ?? '') ?></textarea></div><button class="button button-secondary button-small" type="submit" data-loading-text="Saving…">Save response</button></form></details>
</article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><h2>No published reviews yet</h2><p>Student reviews will appear here after eligible purchases.</p></div><?php endif; ?>
